-- =============================================================================
-- hyprland.lua — Entry point, loads all modules
-- =============================================================================
-- Structure:
--   monitors.lua      → display outputs & scaling
--   environment.lua   → env vars, programs, autostart
--   look-and-feel.lua → gaps, borders, blur, opacity, misc
--   animations.lua    → curves, animation tree, gestures
--   keybindings.lua   → all hl.bind() calls EXCEPT the velocity rice binds
--   velocity-binds.lua → velocity's binds — GENERATED by the velocity flake's
--                        HM module from tools/keybinds-default.json (do not
--                        edit; it is an HM symlink and the single source is
--                        tools/keybinds-default.json in ~/.config/quickshell)
--   rules.lua         → window & layer rules
-- =============================================================================

require("monitors")
require("environment")
require("look-and-feel")
require("animations")
require("keybindings")
require("velocity-binds") -- P3: rendered by programs.velocity (the velocity flake)
require("rules")
